213	fn collect_exports(ast: &Ast) -> HashSet<String> {
214	    let mut exports = HashSet::new();
215	    for node in &ast.declarations {
216	        if let AstNode::Export(inner) = &node.node {
217	            if let Some(name) = declaration_name(&inner.node) {
218	                exports.insert(name.to_string());
219	            }
220	        }
221	    }
222	    exports
223	}
