388	/// Deserialize a JSON object into ordered (key, string-value) pairs without
389	/// silently collapsing duplicate keys the way `serde_json` maps do.
390	// ponytail: consumed by application resolution in Task 7.
391	#[allow(dead_code)]
392	fn raw_json_object_pairs(json: &str) -> Result<Vec<(String, String)>, String> {
393	    struct Pairs;
394	    impl<'de> serde::de::Visitor<'de> for Pairs {
395	        type Value = Vec<(String, String)>;
396	        fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
397	            f.write_str("a JSON object mapping logical paths to source strings")
398	        }
399	        fn visit_map<A: serde::de::MapAccess<'de>>(
400	            self,
401	            mut map: A,
402	        ) -> Result<Self::Value, A::Error> {
403	            let mut out = Vec::new();
404	            while let Some((k, v)) = map.next_entry::<String, serde_json::Value>()? {
405	                match v {
406	                    serde_json::Value::String(s) => out.push((k, s)),
407	                    other => {
408	                        return Err(serde::de::Error::custom(format!(
409	                            "source '{k}' must be a string, found {other}"
410	                        )))
411	                    }
412	                }
413	            }
414	            Ok(out)
415	        }
416	    }
417	    let mut de = serde_json::Deserializer::from_str(json);
418	    let pairs =
419	        serde::de::Deserializer::deserialize_map(&mut de, Pairs).map_err(|e| e.to_string())?;
420	    de.end().map_err(|e| e.to_string())?;
421	    Ok(pairs)
422	}
