424	/// Reference §7 logical-path algorithm: NFC, `/` separators, case preserved,
425	/// `.` segments dropped, `..` resolved without escaping the root; `\`,
426	/// absolute paths, and empty segments rejected.
427	// ponytail: consumed by application resolution in Task 7.
428	#[allow(dead_code)]
429	fn normalize_logical_path(raw: &str) -> Result<String, String> {
430	    let path: String = raw.nfc().collect();
431	    if path.is_empty() {
432	        return Err("empty path".to_string());
433	    }
434	    if path.contains('\\') {
435	        return Err("backslash separators are not allowed".to_string());
436	    }
437	    if path.starts_with('/') {
438	        return Err("absolute paths are not allowed".to_string());
439	    }
440	    let mut segments: Vec<&str> = Vec::new();
441	    for segment in path.split('/') {
442	        match segment {
443	            "" => return Err("empty path segment".to_string()),
444	            "." => {}
445	            ".." => {
446	                if segments.pop().is_none() {
447	                    return Err("path escapes the source-map root".to_string());
448	                }
449	            }
450	            s => segments.push(s),
451	        }
452	    }
453	    if segments.is_empty() {
454	        return Err("path resolves to the source-map root".to_string());
455	    }
456	    Ok(segments.join("/"))
457	}
