530	/// Resolve one deterministic semantic closure from an in-memory source map
531	/// (reference §7). All diagnostics are APP014 with a closed reason value,
532	/// except parse failures which are APP015 (the module fails its language
533	/// schema before closure identity exists).
534	// ponytail: consumed by application resolution in Task 7.
535	#[allow(dead_code)]
536	pub(crate) fn resolve_source_map(
537	    entry_logical_path: &str,
538	    sources: &SourceMap,
539	) -> Result<ResolvedModuleSet, Vec<ApplicationDiagnostic>> {
540	    let mut diags: Vec<ApplicationDiagnostic> = Vec::new();
541	
542	    // Parse every module up front; the set is closed and namespace imports
543	    // need every module's declared namespace anyway.
544	    let mut parsed: IndexMap<String, (String, Ast)> = IndexMap::new();
545	    for (logical_id, source) in &sources.0 {
546	        match parse_source(source) {
547	            Ok(ast) => {
548	                parsed.insert(logical_id.clone(), (source.clone(), ast));
549	            }
550	            Err(e) => {
551	                let mut d = ApplicationDiagnostic::new(
552	                    ApplicationDiagnosticCode::App015,
553	                    format!("module '{logical_id}' failed to parse: {e}"),
554	                )
555	                .with_document_kind("authored_source");
556	                d.context.logical_module_id = Some(logical_id.clone());
557	                diags.push(d);
558	            }
559	        }
560	    }
561	    if !diags.is_empty() {
562	        return Err(diags);
563	    }
564	
565	    let entry = normalize_logical_path(entry_logical_path).map_err(|reason| {
566	        vec![ApplicationDiagnostic::closure_error(
567	            APP014_UNRESOLVED_SPECIFIER,
568	            format!("invalid entry logical path '{entry_logical_path}': {reason}"),
569	        )]
570	    })?;
571	    if !parsed.contains_key(&entry) {
572	        return Err(vec![ApplicationDiagnostic::closure_error(
573	            APP014_UNRESOLVED_SPECIFIER,
574	            format!("entry '{entry}' is not present in sources_json"),
575	        )]);
576	    }
577	
578	    // DFS closure walk from the entry.
579	    let mut std_modules: IndexMap<String, (String, Ast)> = IndexMap::new();
580	    let mut reachable: HashSet<String> = HashSet::new();
581	    let mut visiting: Vec<String> = Vec::new();
582	    let mut import_graph: Vec<ImportEdge> = Vec::new();
583	    let mut aliases: Vec<AliasBinding> = Vec::new();
584	
585	    #[allow(clippy::too_many_arguments)]
586	    fn visit(
587	        logical_id: &str,
588	        parsed: &IndexMap<String, (String, Ast)>,
589	        std_modules: &mut IndexMap<String, (String, Ast)>,
590	        reachable: &mut HashSet<String>,
591	        visiting: &mut Vec<String>,
592	        import_graph: &mut Vec<ImportEdge>,
593	        aliases: &mut Vec<AliasBinding>,
594	        diags: &mut Vec<ApplicationDiagnostic>,
595	    ) {
596	        if visiting.iter().any(|m| m == logical_id) {
597	            let cycle: Vec<&str> = visiting
598	                .iter()
599	                .map(String::as_str)
600	                .chain(std::iter::once(logical_id))
601	                .collect();
602	            diags.push(ApplicationDiagnostic::closure_error(
603	                APP014_IMPORT_CYCLE,
604	                format!("import cycle: {}", cycle.join(" -> ")),
605	            ));
606	            return;
607	        }
608	        if reachable.contains(logical_id) {
609	            return;
610	        }
611	        reachable.insert(logical_id.to_string());
612	        let ast = match parsed
613	            .get(logical_id)
614	            .or_else(|| std_modules.get(logical_id))
615	        {
616	            Some((_, ast)) => ast.clone(),
617	            None => return,
618	        };
619	        visiting.push(logical_id.to_string());
620	        for import in &ast.metadata.imports {
621	            let spec = &import.from_module;
622	            let target: Option<String> = if spec.starts_with("./") || spec.starts_with("../") {
623	                let joined = if logical_dir(logical_id).is_empty() {
624	                    spec.clone()
625	                } else {
626	                    format!("{}/{}", logical_dir(logical_id), spec)
627	                };
628	                match normalize_logical_path(&joined) {
629	                    Ok(p) if parsed.contains_key(&p) => Some(p),
630	                    Ok(p) => {
631	                        diags.push(ApplicationDiagnostic::closure_error(
632	                            APP014_UNRESOLVED_SPECIFIER,
633	                            format!(
634	                                "import '{spec}' in '{logical_id}' resolves to '{p}', which is not in sources_json"
635	                            ),
636	                        ));
637	                        None
638	                    }
639	                    Err(reason) => {
640	                        diags.push(ApplicationDiagnostic::closure_error(
641	                            APP014_UNRESOLVED_SPECIFIER,
642	                            format!("import '{spec}' in '{logical_id}' is invalid: {reason}"),
643	                        ));
644	                        None
645	                    }
646	                }
647	            } else if spec == "std" || spec.starts_with("std:") {
648	                match builtin_std_source(spec) {
649	                    Some(source) => {
650	                        if !std_modules.contains_key(spec) {
651	                            // std sources are maintained in-repo and always parse.
652	                            let ast = parse_source(source).expect("builtin std module parses");
653	                            std_modules.insert(spec.clone(), (source.to_string(), ast));
654	                        }
655	                        Some(spec.clone())
656	                    }
657	                    None => {
658	                        diags.push(ApplicationDiagnostic::closure_error(
659	                            APP014_UNRESOLVED_SPECIFIER,
660	                            format!("unknown std module '{spec}' imported by '{logical_id}'"),
661	                        ));
662	                        None
663	                    }
664	                }
665	            } else {
666	                // Namespace import: exactly one source-map module whose declared
667	                // namespace equals the specifier's exact bytes.
668	                let matches: Vec<&String> = parsed
669	                    .iter()
670	                    .filter(|(_, (_, ast))| ast.metadata.namespace.as_deref() == Some(spec))
671	                    .map(|(id, _)| id)
672	                    .collect();
673	                match matches.as_slice() {
674	                    [one] => Some((*one).clone()),
675	                    [] => {
676	                        diags.push(ApplicationDiagnostic::closure_error(
677	                            APP014_UNRESOLVED_SPECIFIER,
678	                            format!(
679	                                "namespace import '{spec}' in '{logical_id}' matches no source-map module"
680	                            ),
681	                        ));
682	                        None
683	                    }
684	                    _ => {
685	                        diags.push(ApplicationDiagnostic::closure_error(
686	                            APP014_UNRESOLVED_SPECIFIER,
687	                            format!(
688	                                "namespace import '{spec}' in '{logical_id}' matches more than one source-map module"
689	                            ),
690	                        ));
691	                        None
692	                    }
693	                }
694	            };
695	            let Some(target) = target else { continue };
696	            import_graph.push(ImportEdge {
697	                importer: logical_id.to_string(),
698	                imported: target.clone(),
699	            });
700	            if let ImportSpecifier::Wildcard(alias) = &import.specifier {
701	                aliases.push(AliasBinding {
702	                    importer: logical_id.to_string(),
703	                    alias: alias.clone(),
704	                    target: target.clone(),
705	                });
706	            }
707	            visit(
708	                &target,
709	                parsed,
710	                std_modules,
711	                reachable,
712	                visiting,
713	                import_graph,
714	                aliases,
715	                diags,
716	            );
717	            // Named import visibility against the resolved target.
718	            if let ImportSpecifier::Named(items) = &import.specifier {
719	                if let Some((_, target_ast)) =
720	                    parsed.get(&target).or_else(|| std_modules.get(&target))
721	                {
722	                    let exports = collect_exports(target_ast);
723	                    let declared: HashSet<&str> = target_ast
724	                        .declarations
725	                        .iter()
726	                        .filter_map(|d| declaration_name(&d.node))
727	                        .collect();
728	                    for item in items {
729	                        if exports.contains(&item.name) {
730	                            continue;
731	                        }
732	                        if declared.contains(item.name.as_str()) {
733	                            diags.push(ApplicationDiagnostic::closure_error(
734	                                APP014_NOT_EXPORTED,
735	                                format!("'{}' exists in '{target}' but is not exported", item.name),
736	                            ));
737	                        } else {
738	                            diags.push(ApplicationDiagnostic::closure_error(
739	                                APP014_UNRESOLVED_ALIAS,
740	                                format!(
741	                                    "named import '{}' in '{logical_id}' binds no declaration in '{target}'",
742	                                    item.name
743	                                ),
744	                            ));
745	                        }
746	                    }
747	                }
748	            }
749	        }
750	        visiting.pop();
751	    }
752	
753	    visit(
754	        &entry,
755	        &parsed,
756	        &mut std_modules,
757	        &mut reachable,
758	        &mut visiting,
759	        &mut import_graph,
760	        &mut aliases,
761	        &mut diags,
762	    );
763	
764	    if !diags.is_empty() {
765	        crate::application::diagnostic::sort_diagnostics(&mut diags);
766	        return Err(diags);
767	    }
768	
769	    // Deterministic module order: logical ID, bytewise ascending.
770	    let mut logical_ids: Vec<String> = reachable.into_iter().collect();
771	    logical_ids.sort();
772	    let modules: Vec<ResolvedModule> = logical_ids
773	        .iter()
774	        .map(|id| {
775	            let (source, ast) = parsed
776	                .get(id)
777	                .or_else(|| std_modules.get(id))
778	                .expect("reachable module was parsed");
779	            ResolvedModule {
780	                logical_id: id.clone(),
781	                source_hash: source_hash(source),
782	                ast: ast.clone(),
783	            }
784	        })
785	        .collect();
786	
787	    import_graph.sort_by(|a, b| (&a.importer, &a.imported).cmp(&(&b.importer, &b.imported)));
788	    import_graph.dedup();
789	    aliases.sort_by(|a, b| (&a.importer, &a.alias).cmp(&(&b.importer, &b.alias)));
790	
791	    // One qualified symbol table across the closure. Application declaration
792	    // names are NFC-normalized; existing concept names keep exact bytes.
793	    let mut symbols: IndexMap<String, ResolvedSymbol> = IndexMap::new();
794	    for (module_index, module) in modules.iter().enumerate() {
795	        let namespace = module
796	            .ast
797	            .metadata
798	            .namespace
799	            .clone()
800	            // ponytail: modules without @namespace use their logical ID as the
801	            // qualification root; the reference leaves this case to APP014 later.
802	            .unwrap_or_else(|| module.logical_id.clone());
803	        let exports = collect_exports(&module.ast);
804	        for (declaration_index, decl) in module.ast.declarations.iter().enumerate() {
805	            let Some(name) = declaration_name(&decl.node) else {
806	                continue;
807	            };
808	            // Flows are occurrence-identified (reference §8): equal flows are
809	            // legal repetitions, not qualified-ID collisions.
810	            let inner = match &decl.node {
811	                crate::parser::ast::AstNode::Export(inner) => &inner.node,
812	                other => other,
813	            };
814	            if matches!(inner, crate::parser::ast::AstNode::Flow { .. }) {
815	                continue;
816	            }
817	            let kind = declaration_kind(&decl.node);
818	            let name = if kind == ResolvedDeclarationKind::ExistingConcept {
819	                name.to_string()
820	            } else {
821	                name.nfc().collect()
822	            };
823	            let qualified_id = format!("{namespace}.{}.{name}", kind_slug(&decl.node));
824	            let symbol = ResolvedSymbol {
825	                qualified_id: qualified_id.clone(),
826	                kind,
827	                exported: exports.contains(name.as_str()),
828	                origin: OriginRef {
829	                    logical_module_id: module.logical_id.clone(),
830	                    line: decl.line,
831	                    column: decl.column,
832	                },
833	                module_index,
834	                declaration_index,
835	            };
836	            if let Some(existing) = symbols.get(&qualified_id) {
837	                diags.push(ApplicationDiagnostic::closure_error(
838	                    APP014_SYMBOL_COLLISION,
839	                    format!(
840	                        "distinct declarations share qualified ID '{qualified_id}' ('{}' line {} and '{}' line {})",
841	                        existing.origin.logical_module_id,
842	                        existing.origin.line,
843	                        module.logical_id,
844	                        decl.line
845	                    ),
846	                ));
847	            } else {
848	                symbols.insert(qualified_id, symbol);
849	            }
850	        }
851	    }
852	
853	    if diags.is_empty() {
854	        Ok(ResolvedModuleSet {
855	            modules,
856	            import_graph,
857	            symbols,
858	            aliases,
859	        })
860	    } else {
861	        crate::application::diagnostic::sort_diagnostics(&mut diags);
862	        Err(diags)
863	    }
864	}
865	
866	pub fn parse_with_registry(
867	    path: &Path,
868	    registry: &NamespaceRegistry,
869	) -> ParseResult<(Ast, ParseOptions)> {
870	    let content = fs::read_to_string(path).map_err(|e| {
871	        ParseError::GrammarError(format!("Failed to read {}: {}", path.display(), e))
872	    })?;
873	
874	    // `ParseOptions` are constructed here to be returned to the caller,
875	    // even though `parse_source` currently doesn't use them. Initialize
876	    // fields directly in the `ParseOptions` construction to avoid
877	    // field reassignment lint from clippy (clippy::field-reassign-with-default).
878	    let options = ParseOptions {
879	        namespace_registry: Some(registry.clone()),
880	        entry_path: Some(path.to_path_buf()),
881	        ..Default::default()
882	    };
883	
884	    let ast = parse_source(&content)?;
885	    Ok((ast, options))
886	}
