/// Validate that every import in every file resolves to a namespace declared by
/// a file in the set (or `std`/`std:*`). Detects cycles and unexported named
/// imports. Semantic parity with domainforge-core's ModuleResolver but in-memory.
fn resolve_imports(
    files: &[SourceFile],
    asts: &HashMap<String, domainforge_core::parser::ast::Ast>,
    ns_to_uri: &HashMap<String, String>,
) -> Result<(), ForgeError> {
    // Collect exports per namespace.
    let mut ns_exports: HashMap<String, HashSet<String>> = HashMap::new();
    for file in files {
        let ast = &asts[&file.uri];
        let ns = ast.metadata.namespace.clone().unwrap_or_default();
        let exports = collect_exports(ast);
        ns_exports.insert(ns, exports);
    }

    for file in files {
        let ast = &asts[&file.uri];
        for import in &ast.metadata.imports {
            let module = &import.from_module;
            if module == "std" || module.starts_with("std:") {
                continue;
            }
            if !ns_to_uri.contains_key(module) {
                return Err(domain_model_error(format!(
                    "unresolved import: namespace '{module}' not in source set (in {})",
                    file.uri
                )));
            }
            // Check named imports exist in the dependency's exports.
            if let ImportSpecifier::Named(items) = &import.specifier {
                let exports = ns_exports.get(module).cloned().unwrap_or_default();
                for item in items {
                    if !exports.contains(&item.name) {
                        return Err(domain_model_error(format!(
                            "import error: '{}' is not exported by namespace '{}' (in {})",
                            item.name, module, file.uri
                        )));
                    }
                }
            }
        }
    }

    // Cycle detection over the import graph.
    let mut visited = HashSet::new();
    let mut stack = Vec::new();
    for file in files {
        let ast = &asts[&file.uri];
        let file_ns = ast.metadata.namespace.as_deref().unwrap_or("");
        if !file_ns.is_empty() {
            detect_cycle(
                file_ns,
                ns_to_uri,
                asts,
                &mut visited,
                &mut stack,
                MAX_IMPORT_DEPTH,
            )?;
        }
    }
    Ok(())
}

fn detect_cycle(
    ns: &str,
    ns_to_uri: &HashMap<String, String>,
    asts: &HashMap<String, domainforge_core::parser::ast::Ast>,
    visited: &mut HashSet<String>,
    stack: &mut Vec<String>,
    depth_left: usize,
) -> Result<(), ForgeError> {
    if depth_left == 0 {
        return Err(domain_model_error(format!(
            "import depth exceeds limit {MAX_IMPORT_DEPTH}"
        )));
    }
    if stack.contains(&ns.to_string()) {
        let cycle = stack.join(" → ") + " → " + ns;
        return Err(domain_model_error(format!("circular import: {cycle}")));
    }
    if visited.contains(ns) {
        return Ok(());
    }
    visited.insert(ns.to_string());
    stack.push(ns.to_string());

    let Some(uri) = ns_to_uri.get(ns) else {
        stack.pop();
        return Ok(());
    };
    let ast = &asts[uri];
    for import in &ast.metadata.imports {
        let dep = &import.from_module;
        if dep == "std" || dep.starts_with("std:") {
            continue;
        }
        detect_cycle(dep, ns_to_uri, asts, visited, stack, depth_left - 1)?;
    }
    stack.pop();
    Ok(())
}

/// Extract exported declaration names from an AST (mirrors domainforge-core's collect_exports).
fn collect_exports(ast: &domainforge_core::parser::ast::Ast) -> HashSet<String> {
    let mut exports = HashSet::new();
    for node in &ast.declarations {
        if let AstNode::Export(inner) = &node.node {
            if let Some(name) = declaration_name(&inner.node) {
                exports.insert(name.to_string());
            }
        }
    }
    exports
}

fn declaration_name(node: &AstNode) -> Option<&str> {
    match node {
        AstNode::Entity { name, .. }
        | AstNode::Resource { name, .. }
        | AstNode::Flow {
            resource_name: name,
            ..
        }
        | AstNode::Pattern { name, .. }
        | AstNode::Role { name, .. }
        | AstNode::Relation { name, .. }
        | AstNode::Dimension { name } => Some(name),
        _ => None,
    }
}

